use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeSet,fs,path::{Path,PathBuf},process::Command};
fn files(p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){files(&p,v)}else{v.push(p)}}}
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/g2-vector-sign-compat175");let read=|p:&Path|->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()};let hash=|p:&Path|format!("{:x}",Sha256::digest(fs::read(p).unwrap()));
 let a=read(&r.join("analysis.json"));assert_eq!(a["qualified_additional_scope"],true);let pins=read(&r.join("pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(Path::new(p)),h.as_str().unwrap());}
 let mut seen:BTreeSet<String>=serde_json::from_value(read(&r.join("prior-proof-sha256.json"))).unwrap();assert_eq!(seen.len(),26203);let jobs=read(&r.join("jobs.json"));let mut requests=0;let mut exports=0;
 for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let kind=j["kind"].as_str().unwrap();let mut all=vec![];files(Path::new(j["directory"].as_str().unwrap()),&mut all);let proofs=all.into_iter().filter(|p|p.extension().is_some_and(|s|s=="proof")).collect::<Vec<_>>();assert_eq!(proofs.len(),j["exports"].as_u64().unwrap()as usize);
  for proof in proofs{let ph=hash(&proof);let public=proof.with_extension("public");let pu=hash(&public);assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert!(seen.insert(ph.clone()));assert_eq!(pu,j["public_sha256"]);let log=match kind{"resource"=>r.join(format!("runs/{name}/verifier.log")),"concurrent"=>r.join(format!("functional/verify-{name}-{}/stdout.log",proof.file_stem().unwrap().to_str().unwrap())),_=>r.join(format!("functional/verify-{name}/stdout.log"))};let t=fs::read_to_string(log).unwrap();for needle in[format!("VERIFIED proof_sha256={ph}"),format!("public_sha256={pu}"),format!("image_sha256={}",j.get("verification_image_sha256").unwrap_or(&j["image_sha256"]).as_str().unwrap())]{assert!(t.contains(&needle));}exports+=1;}
  requests+=j["SDK_requests"].as_u64().unwrap();
 }
 assert_eq!((requests,exports),(248,89));assert_eq!(seen.len(),26292);assert_eq!(seen,serde_json::from_value(read(&r.join("proof-sha256-after.json"))).unwrap());
 let resources=read(&r.join("resource-result.json"));assert_eq!(resources["passed"],true);let mut units=BTreeSet::new();let mut highs=0;for row in resources["rows"].as_array().unwrap(){assert_eq!(row["passed"],true);assert_eq!(row["metrics"]["memory.max"],"201326592");assert_eq!(row["metrics"]["memory.swap.max"],"0");for k in["max","oom","oom_kill"]{assert_eq!(row["memory_events"][k],0);}highs+=row["memory_events"]["high"].as_u64().unwrap();let unit=row["unit"].as_str().unwrap();assert!(unit.starts_with("zopro-g2-sign-q-"));assert!(units.insert(unit));}
 assert_eq!(units.len(),8);let o=Command::new("systemctl").args(["--user","list-units","--all","--plain","--no-legend","zopro-g2-sign-q-*"]).output().unwrap();assert!(o.status.success());assert!(o.stdout.iter().all(u8::is_ascii_whitespace));let controls=Path::new("/run/user/1000/systemd/user.control");let leftover=if controls.exists(){fs::read_dir(controls).unwrap().map(|e|e.unwrap().file_name().to_string_lossy().into_owned()).filter(|s|s.starts_with("zopro-g2-sign-q-")).collect::<Vec<_>>()}else{vec![]};assert!(leftover.is_empty());
 let mut source=vec![];files(&r.join("source"),&mut source);assert_eq!(source.len(),176);for p in source{let rel=p.strip_prefix(r.join("source")).unwrap();assert_eq!(fs::read(&p).unwrap(),fs::read(Path::new("/home/ubuntu/src/zopro-perf-work/g2-vector-sign-sdk175/source").join(rel)).unwrap());}
 fs::write(r.join("qualification-review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"all89independent_export_bindings_and_freshness_rechecked_without_verifier_reruns":true,"SDK_requests":requests,"exports":exports,"ledger_exact_union":26292,"source_files_exact_to_measured_candidate":176,"resource_cases_passed":8,"memory_high_events":highs,"memory_max_oom_kill_events":0,"swap_max":0,"owned_services_remaining":0,"owned_control_directories_remaining":leftover,"original_source_helper_pins_verified":pins.as_object().unwrap().len(),"original_performance_gate_remains_false":true,"production_changed":false,"performance_or_successful_proof_verifier_reruns":0})).unwrap()).unwrap();println!("IndependentqualificationreviewPASS248SDK/89boundfreshverifiedexports/exactledger26292/176source/8memorycases/ownedunitsclean");
}
